import json
from pathlib import Path
ex=[]
def add(title,topic,level,prompt,urdu,hint,body,tests,headers='',pre='',starter=None):
 code='#include <iostream>\n'+''.join('#include <'+h+'>\n' for h in headers.split())+'\n'+(pre+'\n\n' if pre else '')+'int main() {\n'+ '\n'.join('    '+x for x in body.split('\n'))+'\n}\n'
 ex.append(dict(id=len(ex)+1,title=title,topic=topic,level=level,prompt=prompt,urdu=urdu,hint=hint,solution=code,starter=starter or '#include <iostream>\n'+''.join('#include <'+h+'>\n' for h in headers.split())+'\nint main() {\n    // Write your solution here.\n    return 0;\n}\n',tests=[dict(input=i,expected=o) for i,o in tests]))
add('Your first output','Output','Beginner','Print exactly: Hello, V3school! No input is needed.','بالکل Hello, V3school! دکھائیں۔ ان پٹ کی ضرورت نہیں۔','Use std::cout and a quoted string. Remember the semicolon.','std::cout << "Hello, V3school!";',[('','Hello, V3school!')])
add('Add two numbers','Input & arithmetic','Beginner','Read two integers a and b (−1000 to 1000). Print their sum only.','دو اعداد پڑھیں اور صرف ان کا مجموعہ دکھائیں۔','Read both numbers using std::cin >> a >> b. Print a + b.','int a{}, b{};\nstd::cin >> a >> b;\nstd::cout << a + b;',[('3 4','7'),('-5 2','-3'),('0 0','0')])
add('Even or odd','Conditions','Beginner','Read an integer n (−1000 to 1000). Print Even when n is divisible by 2; otherwise print Odd.','عدد پڑھیں؛ جفت پر Even ورنہ Odd دکھائیں۔','The remainder n % 2 is zero for an even integer.','int n{};\nstd::cin >> n;\nstd::cout << (n % 2 == 0 ? "Even" : "Odd");',[('8','Even'),('7','Odd'),('-4','Even')])
add('Largest of three','Conditions','Beginner','Read three integers. Print the largest value, including when two or more values are equal. Inputs are between −1000 and 1000.','تین اعداد میں سب سے بڑا دکھائیں، برابر قدریں بھی درست سنبھالیں۔','Start with the first value as the largest, then compare the other two.','int a{},b{},c{};\nstd::cin >> a >> b >> c;\nint largest=a;\nif(b>largest)largest=b;\nif(c>largest)largest=c;\nstd::cout << largest;',[('4 9 2','9'),('-3 -8 -1','-1'),('7 7 2','7')])
add('Sum from 1 to n','Loops','Beginner','Read n between 0 and 1000. Use a loop to calculate and print 1 + 2 + … + n. For n = 0 print 0.','لوپ سے ایک سے n تک جمع کریں۔ صفر پر صفر دیں۔','Initialize sum to zero. Add each i from 1 through n.','int n{},sum{};\nstd::cin >> n;\nfor(int i=1;i<=n;++i)sum+=i;\nstd::cout << sum;',[('10','55'),('1','1'),('0','0')])
add('Factorial','Functions & loops','Beginner','Read n between 0 and 12. Print n factorial using a function. Remember 0! = 1.','فنکشن سے n کا factorial دیں؛ صفر کا جواب ایک ہے۔','Start the product at 1, multiply from 2 to n, and return it from a function.','int n{};\nstd::cin >> n;\nstd::cout << factorial(n);',[('5','120'),('0','1'),('12','479001600')],pre='long long factorial(int n) {\n    long long result=1;\n    for(int i=2;i<=n;++i)result*=i;\n    return result;\n}')
add('Sum a sequence','Arrays & vectors','Beginner','Read n (0 to 100), then n integers (−1000 to 1000). Print the sum of the sequence.','پہلے تعداد، پھر اتنے اعداد پڑھ کر جمع دکھائیں۔','Read values into a vector or accumulate each number as you read it.','int n{},sum{};\nstd::cin >> n;\nfor(int i=0;i<n;++i){int x{};std::cin>>x;sum+=x;}\nstd::cout << sum;',[('4\n1 2 3 4','10'),('3\n-2 5 -1','2'),('0','0')])
add('Reverse a word','Strings','Beginner','Read one word of 1 to 100 ASCII letters. Print its characters in reverse order.','ایک لفظ پڑھیں اور اس کے حروف الٹی ترتیب میں دکھائیں۔','std::reverse works with begin() and end(); alternatively traverse from the last character.','std::string word;\nstd::cin >> word;\nstd::reverse(word.begin(),word.end());\nstd::cout << word;',[('hello','olleh'),('a','a'),('level','level')],'string algorithm')
add('Count vowels','Strings & loops','Intermediate','Read one word of ASCII letters. Count a, e, i, o, u, treating uppercase letters as vowels too. Print the count.','لفظ میں چھوٹے اور بڑے حروف والے vowels گنیں۔','Convert safely with std::tolower(static_cast<unsigned char>(c)), then compare with the five vowels.','std::string word;\nstd::cin >> word;\nint count=0;\nfor(unsigned char c:word){char x=static_cast<char>(std::tolower(c));if(x==\'a\'||x==\'e\'||x==\'i\'||x==\'o\'||x==\'u\')++count;}\nstd::cout << count;',[('Education','5'),('sky','0'),('AEIOU','5')],'string cctype')
add('Sort numbers','STL algorithms','Intermediate','Read n (0 to 100), then n integers. Print them in ascending order separated by spaces. Extra surrounding whitespace is ignored.','اعداد چھوٹے سے بڑے ترتیب میں، خالی جگہ سے الگ دکھائیں۔','Use std::vector<int> and std::sort. Include <vector> and <algorithm>.','int n{};\nstd::cin >> n;\nstd::vector<int> v(n);\nfor(int& x:v)std::cin >> x;\nstd::sort(v.begin(),v.end());\nfor(int x:v)std::cout << x << " ";',[('5\n3 1 4 1 2','1 1 2 3 4'),('3\n-1 -3 0','-3 -1 0'),('0','')],'vector algorithm')
add('Count unique values','Sets','Intermediate','Read n (0 to 100), then n integers. Print the number of distinct values.','اعداد میں مختلف قدروں کی تعداد دکھائیں۔','Insert each value into std::set<int>; its size counts unique elements.','int n{};std::cin>>n;\nstd::set<int> values;\nfor(int i=0;i<n;++i){int x{};std::cin>>x;values.insert(x);}\nstd::cout << values.size();',[('5\n1 2 1 3 2','3'),('4\n7 7 7 7','1'),('0','0')],'set')
add('Rectangle class','Classes & objects','Intermediate','Define a Rectangle class with width, height, and an area() method. Read two integers (0 to 1000), create an object, and print its area.','Rectangle کلاس اور area فنکشن بنائیں؛ چوڑائی اور اونچائی سے رقبہ دیں۔','Initialize width and height in a constructor. area() returns width * height.','int w{},h{};std::cin>>w>>h;\nRectangle r{w,h};\nstd::cout << r.area();',[('3 4','12'),('0 8','0'),('10 10','100')],pre='class Rectangle {\n    int width, height;\npublic:\n    Rectangle(int w,int h):width(w),height(h){}\n    int area() const {return width*height;}\n};')
add('Swap by reference','References','Intermediate','Define void swapValues(int&, int&). Read two integers, swap them through the function, and print the new order.','ریفرنس والے فنکشن سے دو اعداد کی جگہ بدلیں اور نئی ترتیب دکھائیں۔','Use a temporary int to preserve the first value while assigning the second.','int a{},b{};std::cin>>a>>b;\nswapValues(a,b);\nstd::cout << a << " " << b;',[('3 8','8 3'),('-1 0','0 -1'),('5 5','5 5')],pre='void swapValues(int& a,int& b){int temp=a;a=b;b=temp;}')
add('Safe division','Exceptions','Intermediate','Read integers a and b (−1000 to 1000). A divide function should throw when b = 0. Print Error for that case; otherwise print the integer quotient.','صفر سے تقسیم پر ایکسپشن دیں اور Error چھاپیں؛ ورنہ integer جواب دیں۔','Throw std::invalid_argument for zero and catch it around the function call.','int a{},b{};std::cin>>a>>b;\ntry{std::cout << divide(a,b);}\ncatch(const std::invalid_argument&){std::cout << "Error";}',[('9 2','4'),('5 0','Error'),('-9 2','-4')],'stdexcept',pre='int divide(int a,int b){if(b==0)throw std::invalid_argument("zero");return a/b;}')
add('Generic maximum','Templates','Advanced','Write a function template that returns the greater of two values. Read two integers and print the result from your template.','ٹیمپلیٹ فنکشن سے دو قدروں میں بڑی قدر دیں۔','Use template<class T> and return a > b ? a : b.','int a{},b{};std::cin>>a>>b;\nstd::cout << maximum(a,b);',[('7 3','7'),('-5 -2','-2'),('4 4','4')],pre='template<class T>T maximum(T a,T b){return a>b?a:b;}')
add('Filter even numbers','Modern C++ & lambdas','Advanced','Read n (0 to 100), then n integers. Use a lambda predicate to print only even numbers in their original order.','لیمبڈا کی شرط سے صرف جفت اعداد اصل ترتیب میں دکھائیں۔','The predicate returns n % 2 == 0. Apply it before printing each value.','int n{};std::cin>>n;\nauto even=[](int x){return x%2==0;};\nfor(int i=0;i<n;++i){int x{};std::cin>>x;if(even(x))std::cout<<x<<" ";}',[('6\n1 2 3 4 5 6','2 4 6'),('3\n1 3 5',''),('4\n-4 -3 0 2','-4 0 2')])
Path('exercises.json').write_text(json.dumps(ex,ensure_ascii=False,indent=2))
print(len(ex),'exercises')
